--liquibase formatted sql
--changeset interview-portal:001-create-roles context:qa,uat
CREATE TABLE "roles" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "role_name" VARCHAR(255) NOT NULL
);
INSERT INTO "roles" ("role_name") VALUES ('ADMIN');
INSERT INTO "roles" ("role_name") VALUES ('INTERVIEWER');

--changeset interview-portal:002-create-users context:qa,uat
CREATE TABLE "users" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "username" VARCHAR(255),
    "password" VARCHAR(255),
    "email" VARCHAR(255),
    "is_active" BOOLEAN,
    "role_id" BIGINT,
    "created_at" TIMESTAMP,
    "updated_at" TIMESTAMP,
    "created_by" BIGINT,
    "updated_by" BIGINT,
    "reset_token" VARCHAR(255),
    "reset_token_expiry" TIMESTAMP,
    "profile_picture" VARCHAR(255)
);
ALTER TABLE "users" ADD CONSTRAINT "fk_users_role" FOREIGN KEY ("role_id") REFERENCES "roles" ("id");

--changeset interview-portal:003-create-candidates context:qa,uat
CREATE TABLE "candidates" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "first_name" VARCHAR(255),
    "last_name" VARCHAR(255),
    "email" VARCHAR(255),
    "experience" INTEGER,
    "designation" VARCHAR(255),
    "is_active" BOOLEAN,
    "created_at" TIMESTAMP,
    "updated_at" TIMESTAMP,
    "created_by" BIGINT,
    "updated_by" BIGINT
);

--changeset interview-portal:004-create-categories context:qa,uat
CREATE TABLE "categories" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "name" VARCHAR(255),
    "is_active" BOOLEAN
);

INSERT INTO "categories" ("is_active", "name") VALUES
    (TRUE, 'Arrays'),
    (TRUE, 'Strings'),
    (TRUE, 'Dynamic Programming'),
    (TRUE, 'Trees & Graphs'),
    (TRUE, 'System Design'),
    (TRUE, 'Java Core')

--changeset interview-portal:005-create-questions context:qa,uat
CREATE TABLE "questions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "title" VARCHAR(255),
    "description" VARCHAR(255),
    "difficulty" VARCHAR(255),
    "estimated_time" INTEGER,
    "is_active" BOOLEAN,
    "created_at" TIMESTAMP,
    "created_by" BIGINT,
    "updated_at" TIMESTAMP,
    "updated_by" BIGINT
);

--changeset interview-portal:006-create-question-designations context:qa,uat
CREATE TABLE "question_designations" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "designation" VARCHAR(255),
    "question_id" BIGINT NOT NULL,
    "created_at" TIMESTAMP
);
ALTER TABLE "question_designations" ADD CONSTRAINT "fk_question_designations_question" FOREIGN KEY ("question_id") REFERENCES "questions" ("id");

--changeset interview-portal:007-create-question-categories context:qa,uat
CREATE TABLE "question_categories" (
    "question_id" BIGINT NOT NULL,
    "category_id" BIGINT NOT NULL
);
ALTER TABLE "question_categories" ADD CONSTRAINT "fk_question_categories_question" FOREIGN KEY ("question_id") REFERENCES "questions" ("id");
ALTER TABLE "question_categories" ADD CONSTRAINT "fk_question_categories_category" FOREIGN KEY ("category_id") REFERENCES "categories" ("id");

--changeset interview-portal:008-create-question-solutions context:qa,uat
CREATE TABLE "question_solutions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "question_id" BIGINT NOT NULL,
    "language" VARCHAR(50) NOT NULL,
    "solution_code" TEXT,
    "is_active" BOOLEAN,
    "created_at" TIMESTAMP,
    "created_by" BIGINT,
    "updated_at" TIMESTAMP,
    "updated_by" BIGINT
);
ALTER TABLE "question_solutions" ADD CONSTRAINT "fk_question_solutions_question" FOREIGN KEY ("question_id") REFERENCES "questions" ("id");

--changeset interview-portal:009-create-assessments context:qa,uat
CREATE TABLE "assessments" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "candidate_id" BIGINT,
    "title" VARCHAR(255),
    "status" VARCHAR(255),
    "time_limit_minutes" INTEGER,
    "is_active" BOOLEAN,
    "started_at" TIMESTAMP,
    "completed_at" TIMESTAMP,
    "created_at" TIMESTAMP,
    "created_by" BIGINT,
    "updated_at" TIMESTAMP,
    "updated_by" BIGINT
);
ALTER TABLE "assessments" ADD CONSTRAINT "fk_assessments_candidate" FOREIGN KEY ("candidate_id") REFERENCES "candidates" ("id");

--changeset interview-portal:010-create-assessment-questions context:qa,uat
CREATE TABLE "assessment_questions" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "assessment_id" BIGINT,
    "question_id" BIGINT,
    "created_at" TIMESTAMP,
    "created_by" BIGINT
);
ALTER TABLE "assessment_questions" ADD CONSTRAINT "fk_assessment_questions_assessment" FOREIGN KEY ("assessment_id") REFERENCES "assessments" ("id");
ALTER TABLE "assessment_questions" ADD CONSTRAINT "fk_assessment_questions_question" FOREIGN KEY ("question_id") REFERENCES "questions" ("id");

--changeset interview-portal:011-create-submissions context:qa,uat
CREATE TABLE "submissions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "assessment_id" BIGINT,
    "reference_file_id" BIGINT,
    "candidate_id" BIGINT,
    "code" VARCHAR(255),
    "output" VARCHAR(255),
    "ai_score" INTEGER,
    "ai_feedback" VARCHAR(255),
    "status" VARCHAR(255),
    "evaluated_at" TIMESTAMP,
    "created_at" TIMESTAMP,
    "created_by" BIGINT,
    "updated_at" TIMESTAMP,
    "updated_by" BIGINT
);
ALTER TABLE "submissions" ADD CONSTRAINT "fk_submissions_assessment" FOREIGN KEY ("assessment_id") REFERENCES "assessments" ("id");
ALTER TABLE "submissions" ADD CONSTRAINT "fk_submissions_candidate" FOREIGN KEY ("candidate_id") REFERENCES "candidates" ("id");
ALTER TABLE "submissions" ADD CONSTRAINT "submissions_assessment_id_key" UNIQUE ("assessment_id");

--changeset interview-portal:012-create-candidate-solutions context:qa,uat
CREATE TABLE "candidate_solutions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "submission_id" BIGINT,
    "question_id" BIGINT,
    "solution" TEXT,
    "ai_score" INTEGER,
    "ai_feedback" TEXT,
    "time_complexity" VARCHAR(255),
    "space_complexity" VARCHAR(255),
    "missed_edge_cases" TEXT,
    "security_issues" TEXT,
    "optimized_code" TEXT,
    "created_at" TIMESTAMP,
    "created_by" BIGINT,
    "updated_at" TIMESTAMP,
    "updated_by" BIGINT
);
ALTER TABLE "candidate_solutions" ADD CONSTRAINT "fk_candidate_solutions_submission" FOREIGN KEY ("submission_id") REFERENCES "submissions" ("id");
ALTER TABLE "candidate_solutions" ADD CONSTRAINT "fk_candidate_solutions_question" FOREIGN KEY ("question_id") REFERENCES "questions" ("id");

--changeset interview-portal:013-create-global-exceptions context:qa,uat
CREATE TABLE "global_exceptions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "error_message" TEXT,
    "stack_trace" TEXT,
    "error_code" INTEGER,
    "user_id" BIGINT,
    "api_endpoint" VARCHAR(500),
    "timestamp" TIMESTAMP
);
ALTER TABLE "global_exceptions" ADD CONSTRAINT "fk_global_exceptions_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id");

--changeset interview-portal:014-create-indexes context:qa,uat
CREATE INDEX "idx_users_username" ON "users" ("username");
CREATE INDEX "idx_users_email" ON "users" ("email");
CREATE INDEX "idx_candidates_email" ON "candidates" ("email");
CREATE INDEX "idx_assessments_candidate_id" ON "assessments" ("candidate_id");
CREATE INDEX "idx_assessments_status" ON "assessments" ("status");
CREATE INDEX "idx_assessment_questions_assessment_id" ON "assessment_questions" ("assessment_id");
CREATE INDEX "idx_assessment_questions_question_id" ON "assessment_questions" ("question_id");
CREATE INDEX "idx_submissions_assessment_id" ON "submissions" ("assessment_id");
CREATE INDEX "idx_submissions_candidate_id" ON "submissions" ("candidate_id");
CREATE INDEX "idx_candidate_solutions_submission_id" ON "candidate_solutions" ("submission_id");
CREATE INDEX "idx_candidate_solutions_question_id" ON "candidate_solutions" ("question_id");
